// Extract and clean the scraped content from Firecrawl response
const inputData = $input.first().json;
const sheetsData = $('Read from Google Sheets').first().json;

try {
  // Get the markdown content from Firecrawl response
  let scrapedContent = inputData.data?.markdown || inputData.data?.content || '';

  // === CLEANING PIPELINE ===

  // 1. Remove all markdown images ![alt](url)
  scrapedContent = scrapedContent.replace(/!\[.*?\]\(.*?\)/g, '');

  // 2. Remove standalone image URLs
  scrapedContent = scrapedContent.replace(/https?:\/\/[^\s]+\.(png|jpg|jpeg|gif|webp|svg)[^\s]*/gi, '');

  // 3. Remove YouTube embed garbage
  scrapedContent = scrapedContent.replace(/Watch later Share Copy link.*?(?=\n\n|\n#|$)/gs, '');
  scrapedContent = scrapedContent.replace(/You're signed out.*?(?=\n\n|\n#|$)/gs, '');
  scrapedContent = scrapedContent.replace(/If playback doesn't begin.*?(?=\n\n|\n#|$)/gs, '');
  scrapedContent = scrapedContent.replace(/\d+:\d+\s*\/\s*\d+:\d+/g, ''); // timestamps like 0:00 / 0:58
  scrapedContent = scrapedContent.replace(/•Live •/g, '');

  // 4. Remove common navigation/UI text patterns
  scrapedContent = scrapedContent.replace(/Search Watch later Share/g, '');
  scrapedContent = scrapedContent.replace(/CancelConfirm/g, '');
  scrapedContent = scrapedContent.replace(/Tap to unmute/g, '');
  scrapedContent = scrapedContent.replace(/More videos/gi, '');
  scrapedContent = scrapedContent.replace(/\[Watch on\]\(.*?\)/g, '');
  scrapedContent = scrapedContent.replace(/Play Uh-oh!.*?(?=\n|$)/g, '');

  // 5. Remove markdown links but keep the text: [text](url) -> text
  scrapedContent = scrapedContent.replace(/\[([^\]]+)\]\([^)]+\)/g, '$1');

  // 6. Remove any remaining URLs
  scrapedContent = scrapedContent.replace(/https?:\/\/[^\s)]+/g, '');

  // 7. Clean up excessive whitespace and newlines
  scrapedContent = scrapedContent.replace(/\n{3,}/g, '\n\n');
  scrapedContent = scrapedContent.replace(/[ \t]{2,}/g, ' ');
  scrapedContent = scrapedContent.replace(/^\s+|\s+$/gm, ''); // trim each line

  // 8. Remove empty headers (# followed by nothing meaningful)
  scrapedContent = scrapedContent.replace(/^#+\s*$/gm, '');

  // Final trim
  const cleanedContent = scrapedContent.trim();

  // Truncate if still too long (8000 chars is plenty for GPT-4o-mini context)
  const maxLength = 10000;
  const finalContent = cleanedContent.length > maxLength 
    ? cleanedContent.substring(0, maxLength) + '\n\n[Content truncated for length]'
    : cleanedContent;

  return [{
    json: {
      about_url: sheetsData.about_url,
      company_name: sheetsData.company_name || 'Unknown Company',
      row_number: sheetsData.row_number,
      scraped_content: finalContent,
      content_length: finalContent.length,
      scrape_success: finalContent.length > 100
    }
  }];

} catch (error) {
  return [{
    json: {
      error: true,
      message: 'Failed to parse Firecrawl response: ' + error.message,
      about_url: sheetsData.about_url,
      company_name: sheetsData.company_name || 'Unknown Company',
      row_number: sheetsData.row_number,
      rawResponse: inputData
    }
  }];
}

// Parse the OpenAI response and prepare for Google Sheets update
const inputData = $input.first().json;
const previousData = $('Parse Scraped Content').first().json;

try {
  // Navigate to the actual response content
  // Structure: output[0].content[0].text contains the JSON object directly
  const outputContent = inputData.output?.[0]?.content?.[0]?.text;

  let parsedResponse;

  if (typeof outputContent === 'object' && outputContent !== null) {
    // Already parsed as object (n8n JSON response format)
    parsedResponse = outputContent;
  } else if (typeof outputContent === 'string') {
    // String response - need to parse
    const cleanedContent = outputContent
      .replace(/```json\n?/g, '')
      .replace(/```\n?/g, '')
      .trim();
    parsedResponse = JSON.parse(cleanedContent);
  } else {
    // Fallback: try older response formats
    const messageContent = inputData.message?.content;
    if (typeof messageContent === 'string') {
      parsedResponse = JSON.parse(messageContent.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim());
    } else if (typeof messageContent === 'object') {
      parsedResponse = messageContent;
    } else {
      throw new Error('Could not find response in expected locations');
    }
  }

  return [{
    json: {
      about_url: previousData.about_url,
      company_name: previousData.company_name,
      row_number: previousData.row_number,
      icebreaker: parsedResponse.icebreaker || 'Failed to generate',
      hook_type: parsedResponse.hook_type || 'unknown',
      confidence: parsedResponse.confidence || 'low',
      status: 'success'
    }
  }];

} catch (error) {
  return [{
    json: {
      about_url: previousData.about_url,
      company_name: previousData.company_name,
      row_number: previousData.row_number,
      icebreaker: 'Error: Could not generate icebreaker',
      hook_type: 'error',
      confidence: 'none',
      status: 'failed',
      error_message: error.message,
      debug_input: JSON.stringify(inputData).substring(0, 500)
    }
  }];
}

// Handle failed scrapes - prepare error message for sheets
const previousData = $('Parse Scraped Content').first().json;

return [{
  json: {
    about_url: previousData.about_url,
    company_name: previousData.company_name,
    row_number: previousData.row_number,
    icebreaker: 'Scrape failed - check URL',
    hook_type: 'error',
    confidence: 'none',
    status: 'scrape_failed'
  }
}];
